let seaGraph16=null;const seaPaths16=new Map();
function clearMarinePaths16(){seaGraph16=null;seaPaths16.clear();}
function sea16(p){return p.x>=-240&&p.x<=3900&&p.y>=0&&p.y<=3900&&!polygon16(p,ATLAS_MAPS.ocean.coast);}
function seaSegment16(a,b){let n=Math.max(2,Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)/12));for(let i=0;i<=n;i++)if(!sea16({x:a.x+(b.x-a.x)*i/n,y:a.y+(b.y-a.y)*i/n}))return false;return true;}
function harborPoint16(c){if(!land16(c)||shore16(c).d>160)return null;let s=shore16(c),len=Math.hypot(s.dx,s.dy);return [1,-1].map(sign=>({x:s.x-sign*s.dy/len*35,y:s.y+sign*s.dx/len*35})).find(sea16)||null;}
function seaGrid16(){if(seaGraph16)return seaGraph16;let step=60,nx=70,ny=66,points=Array.from({length:nx*ny},(_,i)=>({x:-240+(i%nx)*step,y:Math.floor(i/nx)*step}));return seaGraph16={step,nx,ny,points,pass:points.map(sea16)};}
function oceanPath16(a,b){if(!a?.harbor||!b?.harbor)return null;let reverse=a.id>b.id,aa=reverse?b:a,bb=reverse?a:b,k=[aa.id,bb.id,aa.harbor.x,aa.harbor.y,bb.harbor.x,bb.harbor.y].join('|');if(seaPaths16.has(k)){let p=seaPaths16.get(k);return p&&(reverse?{...p,points:[...p.points].reverse()}:p);}let from=aa.harbor,to=bb.harbor,result=null;
 if(seaSegment16(from,to))result={points:[from,to],length:Math.hypot(from.x-to.x,from.y-to.y)};
 else{let {points,pass,nx,ny,step}=seaGrid16();function nearest(p){let best=-1,d=Infinity;for(let i=0;i<points.length;i++){if(!pass[i])continue;let dd=Math.hypot(points[i].x-p.x,points[i].y-p.y);if(dd<d&&seaSegment16(p,points[i])){d=dd;best=i;}}return best;}let start=nearest(from),end=nearest(to);if(start>=0&&end>=0){let dist=new Float64Array(points.length);dist.fill(Infinity);let prev=new Int32Array(points.length);prev.fill(-1);let heap=[];function push(i,d){let n=heap.length;heap.push([i,d]);while(n){let p=(n-1)>>1;if(heap[p][1]<=d)break;heap[n]=heap[p];n=p;}heap[n]=[i,d];}function pop(){let r=heap[0],last=heap.pop();if(heap.length){let i=0;while(i*2+1<heap.length){let j=i*2+1;if(j+1<heap.length&&heap[j+1][1]<heap[j][1])j++;if(heap[j][1]>=last[1])break;heap[i]=heap[j];i=j;}heap[i]=last;}return r;}dist[start]=0;push(start,0);while(heap.length){let [u,d]=pop();if(d!==dist[u])continue;if(u===end)break;let x=u%nx,y=Math.floor(u/nx);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;let xx=x+dx,yy=y+dy;if(xx<0||xx>=nx||yy<0||yy>=ny)continue;let v=yy*nx+xx;if(!pass[v]||!seaSegment16(points[u],points[v]))continue;let nd=d+step*Math.hypot(dx,dy);if(nd<dist[v]){dist[v]=nd;prev[v]=u;push(v,nd);}}}if(Number.isFinite(dist[end])){let ids=[];for(let i=end;i>=0;i=prev[i]){ids.push(i);if(i===start)break;}let raw=[from,...ids.reverse().map(i=>points[i]),to],smooth=[from];for(let i=1;i<raw.length;){let j=raw.length-1;while(j>i&&!seaSegment16(smooth.at(-1),raw[j]))j--;smooth.push(raw[j]);i=j+1;}let length=0;for(let i=1;i<smooth.length;i++)length+=Math.hypot(smooth[i].x-smooth[i-1].x,smooth[i].y-smooth[i-1].y);result={points:smooth,length};}}}
 seaPaths16.set(k,result);return result&&(reverse?{...result,points:[...result.points].reverse()}:result);}
function pathPoint16(path,t){if(!path)return null;let length=Math.max(0,Math.min(1,t))*path.length;for(let i=1;i<path.points.length;i++){let a=path.points[i-1],b=path.points[i],d=Math.hypot(a.x-b.x,a.y-b.y);if(length<=d||i===path.points.length-1){let q=Math.min(1,length/Math.max(.0001,d));return {x:a.x+(b.x-a.x)*q,y:a.y+(b.y-a.y)*q};}length-=d;}return path.points[0];}
function buildHarbor16(id){let c=S.cities[id];if(S.lives<=0||!isOcean16()||!c||c.dormant||c.harbor)return;let point=harborPoint16(c);if(!point)return toast('只可在海洋沿岸建港，五大湖不允许建港');if(S.points<1500)return toast('建港需要 ¥1500');spend(1500,'construction','建设'+c.name+'港口');c.harbor={...point,built:S.day};clearMarinePaths16();save();showDetails();updateUI();toast(c.name+'港口建成 · '+(realCities().filter(x=>x.harbor&&!x.dormant).length<2?'再建一座港口即可开航':'可连接港口，船舶另计'));}
const marineRouteBefore16=routeBridgeStops;
routeBridgeStops=function(stops,type){if(!isMarine16(type))return marineRouteBefore16(stops,type);if(!isOcean16())return {stops,invalid:'轮船只在双洋大陆开放'};for(let i=0;i<stops.length;i++){let c=S.cities[stops[i]];if(!c?.harbor)return {stops,invalid:'海运停靠城市均需先建港口'};if(i&&!oceanPath16(S.cities[stops[i-1]],c))return {stops,invalid:'没有可用的全海洋航道'};}return {stops,invalid:null};};
const marineDraftBefore16=draftCost;
draftCost=function(){if(!isMarine16(draft?.type))return marineDraftBefore16();let route=routeBridgeStops(draft.stops,draft.type),vehicle=!draft.original&&!S.inventory[draft.type]?TYPES[draft.type].vehicle:0;return {bridge:0,tunnel:0,works:0,vehicle,cash:vehicle,length:0,resolved:[...draft.stops],reused:0,invalid:route.invalid};};
const marineCommitBefore16=commitDraft;
commitDraft=function(...a){let type=draft?.type,r=marineCommitBefore16(...a);if(isMarine16(type)&&!draft){for(let [k,v]of Object.entries(S.infrastructure))if(isMarine16(v.type))delete S.infrastructure[k];save();}return r;};
const marineEnterBefore16=canEnter;
canEnter=function(a,b,t,v=null){return isMarine16(t)?!!oceanPath16(a,b):marineEnterBefore16(a,b,t,v);};
const marineEdgeBefore16=edgeTime;
edgeTime=function(a,b,t){if(!isMarine16(t))return marineEdgeBefore16(a,b,t);let path=oceanPath16(a,b);if(!path)return Infinity;let duration=0;for(let i=0;i<9;i++)duration+=1/weatherFactor(pathPoint16(path,i/8),t);return path.length/TYPES[t].speed/researchSpeedFactor(t)*duration/9;};
const marineTravelBefore16=serviceTravelTime;
serviceTravelTime=function(v,l,i,dir){return isMarine16(l.type)?edgeTime(S.cities[l.stops[i]],S.cities[l.stops[i+dir]],l.type):marineTravelBefore16(v,l,i,dir);};
const marineLaneBefore16=lanePoint;
lanePoint=function(a,b,l,t){return !isMarine16(l.type)?marineLaneBefore16(a,b,l,t):pathPoint16(oceanPath16(a,b),t)||{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};};
const marineStrokeBefore16=strokeLaneRange;
strokeLaneRange=function(a,b,l,lo=0,hi=1){if(!isMarine16(l.type))return marineStrokeBefore16(a,b,l,lo,hi);let path=oceanPath16(a,b);ctx.beginPath();if(!path)return;let n=Math.max(2,Math.ceil(path.length*(hi-lo)/15));for(let i=0;i<=n;i++){let p=pathPoint16(path,lo+(hi-lo)*i/n);if(i)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y);}};
const marineCapBefore16=vehCap;
vehCap=function(v){return isMarine16(v.type)?TYPES[v.type].cap:marineCapBefore16(v);};
const marineArrivalBefore16=arrival;
arrival=function(v,l){if(!isMarine16(v.type))return marineArrivalBefore16(v,l);if(v.recall||v.pendingService||S.lines.find(x=>x.id===v.line)?.retiring)v.dock16={phase:'off',credit:0};else v.dock16??={phase:'off',credit:0};v.t=0;v.dwell=0;};
function dockMarine16(v,l,dt){let live=S.lines.find(x=>x.id===v.line),city=S.cities[l.stops[v.index]];if(!live||!city)return;if(v.stops&&live.stops.includes(city.id)){v.index=live.stops.indexOf(city.id);v.stops=null;l=live;}let dock=v.dock16,retiring=live.retiring||v.recall||!!v.pendingService;dock.credit+=dt*(dock.phase==='off'?(v.type==='ship'?8:20):(v.type==='ship'?20:50));let next=departureIndex(v,l),nextId=next>=0?l.stops[next]:null;
 let previousBatch=routingBatch;routingBatch={routes:new Map(),travel:new Map()};try{if(dock.phase==='off'){let off=v.people.filter(p=>{if(retiring||matchesDestination(city,p))return true;let r=plan(city.id,p,{onboard:v});return !(r?.line===l.id&&r.next===nextId&&r.vehicleIds.includes(v.id));}),count=Math.min(off.length,Math.floor(dock.credit));for(let p of off.slice(0,count)){v.people.splice(v.people.indexOf(p),1);if(!finishPassengerAtCity(p,city)){p.ready=1;city.q.push(p);}}dock.credit-=count;if(count<off.length)return;if(retiring){if(v.pendingService&&!v.recall&&!live.retiring){v.service=v.pendingService;delete v.pendingService;}else{delete v.dock16;retireVehicleAsset(v);return;}}dock.phase='on';dock.credit=0;return;}
 city.q.sort((a,b)=>b.wait-a.wait);let willing=city.q.filter(p=>{if(p.ready>0)return false;let r=plan(city.id,p,{boarding:v});return r?.line===l.id&&r.next===nextId&&r.vehicleIds.includes(v.id);}),space=Math.max(0,vehCap(v)-v.people.length),count=Math.min(space,willing.length,Math.floor(dock.credit));for(let p of willing.slice(0,count)){city.q.splice(city.q.indexOf(p),1);v.people.push(p);p.usedShip16=true;}dock.credit-=count;if(willing.length>count&&space>count)return;delete v.dock16;v.dwell=.15;v.dwellMax=.15;
 }finally{routingBatch=previousBatch;}}
function tickMarine16(v,l,dt){for(let p of v.people)p.journey=(p.journey||0)+dt;if(v.dock16){dockMarine16(v,l,dt);return;}if(v.dwell>0){v.dwell=Math.max(0,v.dwell-dt);return;}let next=v.t>0?v.index+v.dir:departureIndex(v,l);if(next<0||next>=l.stops.length){v.parked=true;if(v.recall)arrival(v,l);return;}let a=S.cities[l.stops[v.index]],b=S.cities[l.stops[next]],path=oceanPath16(a,b),time=path?path.length/TYPES[l.type].speed/researchSpeedFactor(l.type)/weatherFactor(pathPoint16(path,v.t),l.type):Infinity;if(!Number.isFinite(time)){v.parked=true;return;}v.parked=false;if(typeof prepareDeparture1614==='function'&&!prepareDeparture1614(v,l)){v.dock16={phase:'on',credit:0};return;}v.t+=dt/Math.max(.2,time);if(v.t>=1){for(let p of v.people)recordSegment(p,a,b,l.type);v.index=next;v.t=0;arrival(v,l);}}
const marineAddBefore16=addVehicle;
